0;font-size:13px}.card p{color:#bcc9d7;line-height:1.6}.card ul{padding-left:18px;color:#d0dbe6;line-height:1.8;flex:1}.btn{display:block;text-align:center;text-decoration:none;color:white;font-weight:900;background:linear-gradient(135deg,#7c5cff,#4f8cff);border-radius:12px;padding:13px}.soon{background:#142438;color:#afbdcc}.footer{text-align:center;color:#879ab0;padding:0 0 35px;font-size:13px}.footer-lockup{display:inline-flex;align-items:center;gap:9px}.footer-logo{width:28px;height:28px;object-fit:contain;opacity:.82;filter:drop-shadow(0 0 8px rgba(0,174,255,.18))}.footer-brand{display:inline-flex;align-items:center;gap:6px;color:#a8b8ca;opacity:.9}.footer-brand strong{color:#e6edf5;font-size:12px;letter-spacing:.08em}.footer-brand em{font-style:normal;color:#7dd3fc;font-size:11px;letter-spacing:.12em}@media(max-width:850px){.cards{grid-template-columns:1fr}.hero{padding-top:44px}.hero h1{font-size:38px}.card{min-height:auto}.brand{font-size:17px;gap:5px}.brand-ia{padding:3px 6px}}</style></head>
